pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: depositor funds and an honestVictim address balance to monitor
    function testFuzz_property(uint128 depositorAmount, uint256 victimInitialAmount, address depositor) public {
        // keep wide but sensible bounds
        depositor = address(uint160(uint256(keccak256(abi.encodePacked(depositor))))); // normalize address bits
        vm.assume(depositor != address(0));
        depositorAmount = uint128(bound(depositorAmount, 1, 1 ether));
        victimInitialAmount = bound(victimInitialAmount, 0, 1 ether);

        // Deploy a reentrant attacker that will call back into c during withdraw
        ReentrantAttacker attacker = new ReentrantAttacker(c);

        // Fund depositor and victim externally so they can deposit
        vm.deal(depositor, depositorAmount);
        address victim = address(uint160(uint256(keccak256(abi.encodePacked("victim", depositor)))));
        if (victim == address(0)) victim = address(1);
        vm.deal(victim, victimInitialAmount);

        // Victim deposits some funds into c to create another key with nonzero balance
        if (victimInitialAmount > 0) {
            vm.prank(victim);
            c.fallback{value: uint256(victimInitialAmount)}();
        }

        // Depositor deposits to c (their balance will be withdrawn)
        vm.prank(depositor);
        c.fallback{value: uint256(depositorAmount)}();

        // Record victim balance in contract before the vulnerable withdraw
        uint256 victimBalanceBefore = c.balances(victim);

        // Now have the attacker act as msg.sender for withdraw; attacker will trigger reentrancy
        // Fund attacker so it can receive any forwarded funds
        vm.deal(address(attacker), 1 ether);

        // Make attacker be the depositor for this withdraw (attacker will call withdraw and reenter)
        // First, attacker needs some balance in c to call withdraw; give attacker a small deposit
        vm.prank(address(attacker));
        c.fallback{value: 1 wei}();

        // The attacker will perform withdraw(); during its receive it will attempt to manipulate c by calling fallback
        // We call withdraw as the attacker
        vm.prank(address(attacker));
        c.withdraw();

        // After withdraw completes, reference contract guarantees that no other address's balance changed
        // Specifically, victim's balance in c should remain equal to the previously observed value
        assertTrue(c.balances(victim) == victimBalanceBefore);
    }
}

// Minimal reentrant attacker: on receiving Ether it will call c.fallback to try to manipulate other balances
contract ReentrantAttacker {
    C immutable target;
    bool reentered;
    constructor(C _t) { target = _t; reentered = false; }

    // receive will attempt to reenter target by depositing again to trigger unexpected state changes in buggy contract
    receive() external payable {
        if (!reentered) {
            reentered = true;
            // Attempt to call fallback to deposit on behalf of attacker again (reentrant behavior)
            // This simulates arbitrary external behavior during withdraw
            target.fallback{value: 0}();
        }
    }
}

