        vm.assume(depositor != address(0));
        vm.assume(victim != address(0));
        vm.assume(depositor != victim);
        uint256 amt = bound(amount, 1, 1 ether);

        // fund depositor and victim so they can deposit
        vm.deal(depositor, 2 ether);
        vm.deal(victim, 2 ether);

        // victim makes a deposit to record an initial balance under their address
        vm.prank(victim);
        // call fallback by sending ether to contract
