        require(sent);
        uint256 victimBefore = c.balances(victim);

        // Deploy an attacker that will reenter during withdraw
        Attacker att = new Attacker(c, victim);

        // depositor deposits some funds so they can call withdraw; make depositor be the attacker contract's owner
        vm.prank(depositor);
        (bool sent2,) = address(c).call{value: amt}('');
        require(sent2);

        // Now have the attacker trigger withdraw on behalf of depositor by calling withdraw while the attacker reenters
        // We set attacker.owner to depositor so that attacker can receive any refunds if needed
        att.setDepositor(depositor);

        // The attacker will call c.withdraw() (attacker calls withdraw, which will reenter via its receive), so prank the attacker address
        // but we need the attacker to be the msg.sender of withdraw; attacker will itself call withdraw
