        vm.deal(address(att), 1 ether);

        // attacker triggers withdraw while performing a reentrant call to c (via receive)
        // This models an external party that during withdraw can reenter and attempt to modify balances of arbitrary keys (victim)
        att.attack{value: 0}();

        // After the withdraw completes, the correct contract guarantees victim's balance is unchanged
        // The mutant without lock can change balances(victim). We assert the preserved property that holds for correct contract.
        assertTrue(c.balances(victim) == victimBefore);
    }
