    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor (who will deposit and then withdraw via attacker) and an extra address probe
    function testFuzz_property(address depositor, address probe, uint256 depositAmount) public {
        // keep domain sensible but wide
        vm.assume(depositor != address(0));
        vm.assume(probe != address(0));
        // avoid trivial tiny amounts
        depositAmount = bound(depositAmount, 1, 1 ether);

        // Deploy a reentrant attacker that will call into c.withdraw when it receives Ether
        Attacker att = new Attacker(address(c));

        // Fund depositor so they can deposit
        vm.deal(depositor, depositAmount);
        // depositor deposits by sending Ether (fallback adds to balances)
        vm.prank(depositor);
        (bool okDeposit, ) = address(c).call{value: depositAmount}("");
        require(okDeposit);

        // Also set some balance for probe to have nonzero recorded balance (so sum includes other keys)
        // We simulate probe depositing some small value
        uint256 probeAmt = 1;
        vm.deal(probe, probeAmt);
        vm.prank(probe);
        (bool okP, ) = address(c).call{value: probeAmt}("");
        require(okP);

        // Compute sum of balances before withdraw by reading public getter for both addresses
        uint256 sumBefore = c.balances(depositor) + c.balances(probe);
        // also include contract balance of any other remaining (should equal sumBefore)
        uint256 contractBalBefore = address(c).balance;

        // Sanity: in correct contract these should match
        // Now perform withdraw: depositor routes call through attacker contract so attacker can reenter
        // Attacker will reenter and attempt to manipulate balances during withdraw if mutant allows
        vm.prank(depositor);
        // Make the attacker the msg.sender for withdraw by having depositor call attacker which forwards
        // The attacker contract's callWithdraw will call c.withdraw() from its own address
        // Send no value; c.withdraw is non-payable
        att.callWithdrawAs{value: 0}();

        // After withdraw completes, read balances and contract balance
        uint256 sumAfter = c.balances(depositor) + c.balances(probe);
        uint256 contractBalAfter = address(c).balance;

        // General invariant: the sum of recorded balances equals the contract's Ether balance
        // This holds for the reference C for all inputs; the mutant without the reentrancy lock can break it
        assertTrue(sumAfter == contractBalAfter);
    }
}

